function taylorB  clc;  #Primero ingreso el punto alrededor y luego  #el punto a evaluar  x=input("Ingrese un punto a lrededor quiere calcular el polinomio: ");  y=input("ingrese en que punto desea evaluar el polinomio y la funcion: ");    #aqui controlo que no sea 0, ya que la funcion no  #esta definifa en ese punto  indeterminacion (1/0)  if x<0 || y<0    display("La funcion no esta definida en ese punto")    return;  endif    #aqui evaluo en el primer termino del polinomio  d0=e^(sqrt(x));  #aqui evaluo en el segundo termino del polinomio  d1=(e^(sqrt(x)))/(2*sqrt(x));  #aqui evaluo en el tercer termino del polinomio  d2=-((x-x^(3/2))*e^(sqrt(x)))/(4*x^(5/2));  #aqui evaluo en el cuarto termino del polinomio  d3=((x^5 - 3*x^(9/2) + 3*x^(4))*e^(sqrt(x)))/(8*x^(13/2));  #aqui evaluo en el quinto termino del polinomio  d4=-((-x^(25/2) +6*x^(12) -15*x^(23/2) +15*x^(11))*e^(sqrt(x)))/(16*x^(29/2));  #calcular el punto a evaluar en el polinomio  sol=d0+(d1)*(y-x) + ((d2/2)*(y-x)^2) + ((d3/6)*(y-x)^3) + ( (d4/24)*(y-x)^4 );  #calcular el punto en la funcion original  real=e^(sqrt(y));    #muestro las respuestas  display("La solucion en el punto mediante el polinomio es:")  display(sol);  display("La solucion en el punto en la funcion original el: ")  display(real)  #defino un rango de valores para hacer la grafica  #comienza desde el punto donde hago mi polinomio hasta el punto a evaluar  #controlo que vaya graficando desde el punto menor hasta el mayor  if x<y || x==y    m=0:0.0001:y+0.05;  endif    if x>y    m=0:0.0001:x+0.05;  endif    #hago las graficas   hold on  grid on  grid minor  plot(m,d0+(d1)*(m-x) + ((d2/2)*(m-x).^2) + ((d3/6)*(m-x).^3) + ( (d4/24)*(m-x).^4 ),'linewidth',1)  plot(m,d0+(d1)*(m-x) + ((d2/2)*(m-x).^2) + ((d3/6)*(m-x).^3),'linewidth',0.5)  plot(m,d0+(d1)*(m-x) + ((d2/2)*(m-x).^2),'linewidth',0.5)  plot(m,d0+(d1)*(m-x),'linewidth',0.5)  plot(m,e.^(sqrt(m)),'linewidth',0.5)  legend('p4','p3','p2','p1','f')    #calculo el eror relativo  errRelativo=100*abs((real-sol)/real);  #muestro el error relativo  display("El error relativo porcentual es: ")  display(errRelativo)  endfunction